gXQ(){return"\u0633\u067e\u0644\u0627\u0626\u0631 \u0639\u0645\u0631 \u0631\u0633\u06cc\u062f\u06c1 \u0631\u067e\u0648\u0631\u0679"},
gXR(){return"\u0633\u067e\u0644\u0627\u0626\u0631 \u0639\u0645\u0631 \u0631\u0633\u06cc\u062f\u06c1 \u062e\u0644\u0627\u0635\u06c1"},
gWP(){return"\u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0648\u0627\u067e\u0633\u06cc \u0631\u062c\u0633\u0679\u0631"},
gWQ(){return"\u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0648\u0627\u067e\u0633\u06cc \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1"},
gWI(){return"\u067e\u0631\u0648\u0688\u06a9\u0679 \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0648\u0627\u067e\u0633\u06cc \u0644\u06cc\u062c\u0631"},
gOX(){return"\u0641\u0631\u0648\u062e\u062a \u06a9\u06cc \u0631\u0633\u06cc\u062f"},
