gado(){return"\u0633\u06cc\u0644\u0632 \u0627\u0646\u0648\u0627\u0626\u0633 (\u062a\u0641\u0635\u06cc\u0644\u06cc) \u0641\u0627\u0631\u0645 \u0627\u06cc\u06a9 \u062c\u0627\u0645\u0639 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u06c1\u06d2 \u062c\u0648 \u0633\u06cc\u0644\u0632 \u0679\u0631\u0627\u0646\u0632\u06cc\u06a9\u0634\u0646 \u06a9\u06cc \u062a\u0641\u0635\u06cc\u0644\u06cc \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u0648 \u067e\u06a9\u0691\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0645\u06cc\u06ba \u0645\u0635\u0646\u0648\u0639\u0627\u062a \u06cc\u0627 \u062e\u062f\u0645\u0627\u062a \u06a9\u06cc \u062a\u0641\u0635\u06cc\u0644\u060c \u0645\u0642\u062f\u0627\u0631\u06cc\u06ba\u060c \u06cc\u0648\u0646\u0679 \u0642\u06cc\u0645\u062a\u06cc\u06ba\u060c \u0627\u0648\u0631 \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u0631\u0639\u0627\u06cc\u062a\u06cc\u06ba \u06cc\u0627 \u0679\u06cc\u06a9\u0633 \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u06d4"},
gOY(){return"\u0633\u06cc\u0644\u0632 \u0627\u0646\u0648\u0627\u0626\u0633 (\u0645\u062e\u062a\u0635\u0631)"},
gadq(){return"\u0633\u06cc\u0644\u0632 \u0627\u0646\u0648\u0627\u0626\u0633 (\u0645\u062e\u062a\u0635\u0631) \u0627\u06cc\u06a9 \u0645\u062e\u062a\u0635\u0631 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u06c1\u06d2 \u062c\u0648 \u0633\u06cc\u0644\u0632 \u0679\u0631\u0627\u0646\u0632\u06cc\u06a9\u0634\u0646 \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u067e\u06cc\u0634 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u06cc\u06c1 \u0641\u0631\u0648\u062e\u062a \u06a9\u06cc \u06af\u0626\u06cc \u0627\u0634\u06cc\u0627\u0621 \u06cc\u0627 \u062e\u062f\u0645\u0627\u062a\u060c \u0627\u0646 \u06a9\u06cc \u0645\u0642\u062f\u0627\u0631\u06cc\u06ba\u060c \u0627\u0648\u0631 \u06a9\u0644 \u0631\u0642\u0645 \u06a9\u06cc \u0627\u06cc\u06a9 \u062a\u06cc\u0632 \u062c\u06be\u0644\u06a9 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},
