gadt(){return"\u0633\u06cc\u0644\u0632 \u0622\u0631\u0688\u0631 \u0645\u06cc\u0646\u0648 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0633\u06cc\u0644\u0632 \u0622\u0631\u0688\u0631\u0632 \u06a9\u0648 \u0622\u0633\u0627\u0646\u06cc \u0633\u06d2 \u062a\u062e\u0644\u06cc\u0642\u060c \u0645\u0646\u0638\u0645\u060c \u0627\u0648\u0631 \u0679\u0631\u06cc\u06a9 \u06a9\u0631\u06cc\u06ba\u06d4 \u0627\u067e\u0646\u06d2 \u0633\u06cc\u0644\u0632 \u06a9\u06d2 \u0639\u0645\u0644 \u06a9\u0648 \u0633\u0627\u062f\u06c1 \u06a9\u0631\u06cc\u06ba\u060c \u0622\u0631\u0688\u0631\u0632 \u0628\u0646\u0627\u0646\u06d2 \u0633\u06d2 \u0644\u06d2 \u06a9\u0631 \u0622\u0631\u0688\u0631 \u06a9\u06cc \u062a\u06a9\u0645\u06cc\u0644 \u062a\u06a9\u060c \u0633\u0628 \u0627\u06cc\u06a9 \u06c1\u06cc \u062c\u06af\u06c1 \u067e\u0631\u06d4"},
gWW(){return"\u0642\u0648\u0679\u06cc\u0634\u0646"},
gatU(){return"\u067e\u0631\u0648\u0641\u06cc\u0634\u0646\u0644 \u0627\u0648\u0631 \u062a\u0641\u0635\u06cc\u0644\u06cc \u06a9\u0648\u0679\u06cc\u0634\u0646\u0632 \u0622\u0633\u0627\u0646\u06cc \u0633\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u06cc\u06ba\u06d4 \u0627\u067e\u0646\u06d2 \u0645\u0645\u06a9\u0646\u06c1 \u06a9\u0644\u0627\u0626\u0646\u0679\u0633 \u06a9\u0648 \u062f\u0631\u0633\u062a \u0642\u06cc\u0645\u062a\u0648\u06ba \u0627\u0648\u0631 \u0645\u0635\u0646\u0648\u0639\u0627\u062a \u06a9\u06cc \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u062a\u0627\u062b\u0631 \u06a9\u0631\u06cc\u06ba\u060c \u062a\u0627\u06a9\u06c1 \u0622\u067e \u0633\u0648\u062f\u06d2 \u0628\u0627\u0646\u062f\u06be \u0633\u06a9\u06cc\u06ba \u0627\u0648\u0631 \u0646\u0626\u06d2 \u06a9\u0627\u0631\u0648\u0628\u0627\u0631 \u062c\u06cc\u062a \u0633\u06a9\u06cc\u06ba\u06d4"},
